import numpy as np

class OneDimKalman:
    def __init__(self):
        self.state = np.array([[1.0], [2.0]])

    def predict(self, dt):
        F = np.array([[1.0, dt], [0.0, 1.0]])
        self.state = F @ self.state
        return self.state

kf = OneDimKalman()
result = kf.predict(1.0)

